#=============================================================================
#run_synthetic_benchmark.py
#=============================================================================
#Synthetic Benchmark Execution Framework for MODE-py
#This script executes object-based verification experiments using
#synthetic benchmark datasets generated by synthetic_generator.py.

#Usage:
#  python run_synthetic_benchmark.py --suite static --case displacement
#  python run_synthetic_benchmark.py --suite dynamic --case splitting_storm
#=============================================================================


import warnings
warnings.filterwarnings('ignore')
import os
import sys
import argparse
import pickle
import xarray as xr

from mode_verifier import MODE3DVerifier
import config


# Root path 
CURRENT_DIR = os.path.dirname(os.path.abspath(__file__))
ROOT_DIR = os.path.abspath(os.path.join(CURRENT_DIR, ".."))
sys.path.append(ROOT_DIR)


##-----------------------------------------------------------------------------
# ARGUMENT PARSER
##-----------------------------------------------------------------------------

def parse_arguments():
    parser = argparse.ArgumentParser(
        description="Run MODE synthetic benchmark for a specific suite and case."
    )
    parser.add_argument(
        "--suite",
        type=str,
        choices=["static", "dynamic"],
        required=True,
        help="Benchmark suite to run: 'static' or 'dynamic'"
    )
    parser.add_argument(
        "--case",
        type=str,
        required=True,
        help="Specific case name (e.g., 'displacement', 'splitting_storm')"
    )
    parser.add_argument(
        "--output_dir",
        type=str,
        default="synthetic_benchmark_results",
        help="Base output directory for benchmark results (default: synthetic_benchmark_results)"
    )
    return parser.parse_args()

##-----------------------------------------------------------------------------
# MAIN 
##-----------------------------------------------------------------------------

if __name__ == "__main__":
    args = parse_arguments()
    
    # Dynamic path configuration based on arguments
    DATA_DIR = f"synthetic_output/{args.suite}"
    CASE_NAME = args.case
    SUITE_OUTPUT_DIR = os.path.join(args.output_dir, args.suite, CASE_NAME)
    
    # Ensure the specific output directory exists
    os.makedirs(SUITE_OUTPUT_DIR, exist_ok=True)
    
    print("\n" + "="*70)
    print(f"RUNNING BENCHMARK: Suite='{args.suite.upper()}', Case='{CASE_NAME}'")
    print("="*70 + "\n")

    # Load NETCDF files  
    wrf_file = os.path.join(DATA_DIR, f"synthetic_wrf_{CASE_NAME}.nc")
    gpm_file = os.path.join(DATA_DIR, f"synthetic_gpm_{CASE_NAME}.nc")
    
    if not os.path.exists(wrf_file) or not os.path.exists(gpm_file):
        print(f"ERROR: Files not found in {DATA_DIR}")
        print(f"  Expected WRF: {wrf_file}")
        print(f"  Expected GPM: {gpm_file}")
        sys.exit(1)

    print("Loading synthetic datasets...\n")
    wrf_ds = xr.open_dataset(wrf_file)
    gpm_ds = xr.open_dataset(gpm_file)

    # Extract precipitation
    forecast = wrf_ds["precipitation"]
    observed = gpm_ds["precipitation"]

    # MODE-py parameters
    mode_params = config.SYNTHETIC_MODE_PARAMS.copy()
    interest_threshold = mode_params.pop("interest_threshold")

    # Initialize MODE-py
    print("\nInitializing MODE-py verifier...\n")
    verifier = MODE3DVerifier(
        forecast=forecast,
        observed=observed,
        **mode_params
    )

    # Run Verification 
    print("\nRunning MODE-py verification...\n")
    metrics = verifier.run_verification(interest_threshold=interest_threshold)
    print("\nVerification completed!\n")

    # Print metrics
    print("\n" + "="*70)
    print("BENCHMARK METRICS")
    print("="*70)
    for k, v in metrics.items():
        print(f"{k:>35}: {v}")

    # Generate figures
    print("\nGenerating diagnostic figures...\n")
    for time_idx in range(forecast.time.size):
        verifier.plot_matched_objects(time_idx=time_idx)

    # Save metrics to csv 
    verifier.save_metrics_to_csv()
    
    pkl_file = os.path.join(SUITE_OUTPUT_DIR, f"benchmark_{CASE_NAME}.pkl")
    with open(pkl_file, "wb") as f:
        pickle.dump(verifier, f)
        
    print(f"\nVerifier object saved: {pkl_file}")
    print(f"Results organized in: {SUITE_OUTPUT_DIR}")
    print("\nSynthetic benchmark completed successfully!\n")
